defmodule Soak.MixProject do
  use Mix.Project

  def project do
    [app: :soak, version: "0.1.0", elixir: "~> 1.18", deps: deps()]
  end

  def application do
    [extra_applications: [:logger], mod: {Soak.Application, []}]
  end

  # The SDKs are generated by setup.sh, with Infusion from Hex.
  defp deps do
    [
      {:github_sdk, path: "sdks/github"},
      {:coingecko, path: "sdks/coingecko"},
      {:infusion_runtime, "~> 0.2.1"},
      {:jason, "~> 1.4"}
    ]
  end
end
